; table.asm -- chapter 11: one of 8 routines, by a table and by a chain
; generated by gen11.py
        INCLUDE "msx.inc"
        OUTPUT "table.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
which   EQU RAM_START          ; 16 bytes: what each call answered
; One of 8 routines chosen by the number in A: through a table of their
; addresses and JP (HL), and through a chain of CP and JR Z. Each routine
; answers with its own number times 17, and the answers go into which.
init:   di
        ld sp, SYS_AREA
        ld a, 0
a0:     call dispatch
        ld (which + 0), a       ; the routine that ran
        ld a, 0
b0:     call chain
        ld (which + 8), a
        ld a, 1
a1:     call dispatch
        ld (which + 1), a       ; the routine that ran
        ld a, 1
b1:     call chain
        ld (which + 9), a
        ld a, 2
a2:     call dispatch
        ld (which + 2), a       ; the routine that ran
        ld a, 2
b2:     call chain
        ld (which + 10), a
        ld a, 3
a3:     call dispatch
        ld (which + 3), a       ; the routine that ran
        ld a, 3
b3:     call chain
        ld (which + 11), a
        ld a, 4
a4:     call dispatch
        ld (which + 4), a       ; the routine that ran
        ld a, 4
b4:     call chain
        ld (which + 12), a
        ld a, 5
a5:     call dispatch
        ld (which + 5), a       ; the routine that ran
        ld a, 5
b5:     call chain
        ld (which + 13), a
        ld a, 6
a6:     call dispatch
        ld (which + 6), a       ; the routine that ran
        ld a, 6
b6:     call chain
        ld (which + 14), a
        ld a, 7
a7:     call dispatch
        ld (which + 7), a       ; the routine that ran
        ld a, 7
b7:     call chain
        ld (which + 15), a
stop:   jr stop

; dispatch: the routine whose number is in A, through the table
dispatch:
        add a, a                ; two bytes to an address
        ld l, a
        ld h, 0
        ld de, routines
        add hl, de              ; HL: the routine's place in the table
        ld e, (hl)
        inc hl
        ld d, (hl)              ; DE: its address, low byte first
        ex de, hl
        jp (hl)                 ; and there; its RET comes back to the CALL

; chain: the same routine, by asking about each number in turn
chain:  or a
        jr z, r0
        cp 1
        jr z, r1
        cp 2
        jr z, r2
        cp 3
        jr z, r3
        cp 4
        jr z, r4
        cp 5
        jr z, r5
        cp 6
        jr z, r6
        cp 7
        jr z, r7
        ret

routines:
        dw r0, r1, r2, r3, r4, r5, r6, r7
r0:     ld a, 0                 ; routine 0 answers 0
        ret
r1:     ld a, 17                ; routine 1 answers 17
        ret
r2:     ld a, 34                ; routine 2 answers 34
        ret
r3:     ld a, 51                ; routine 3 answers 51
        ret
r4:     ld a, 68                ; routine 4 answers 68
        ret
r5:     ld a, 85                ; routine 5 answers 85
        ret
r6:     ld a, 102               ; routine 6 answers 102
        ret
r7:     ld a, 119               ; routine 7 answers 119
        ret
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
